      perfect: ["Perfect tense (have/has/had + p.p.)", "Something finished or continuing up to a point in time; often with already, just, ever or since."],
      relative: ["Relative clause (who / which / whose)", "who (people), which (things) and whose (possession) start a clause that tells us more about the noun before it."],
      compare: ["Comparatives and superlatives", "Compare two things with -er / more … than; the top one of a group with the -est / the most …; equal with as … as."],
      modal: ["Modal + base verb", "can, could, may, might, must, should and would are followed by the base verb to show ability, possibility, duty or advice."],
      future: ["Future (will / be going to)", "will + base verb or be going to + base verb for future events and plans."],
      ifClause: ["Conditional (if / unless)", "if means 'on the condition that', unless means 'except if'; the if-clause uses the present tense for the future."],
      whTo: ["Question word + to V", "how / what / where / when + to + base verb means 'how one should …'; common in headlines."],
      thereBe: ["There + be", "Says that something exists; the verb agrees with the noun that follows."],
      gerund: ["Gerund as subject (V-ing)", "A V-ing phrase can be the subject of a sentence; it takes a singular verb."],
      question: ["Question headline", "Headlines ask questions to make readers curious; the auxiliary or be verb comes before the subject."],
